// #146331 — candidate_start_attempt под нагрузкой (VOICE-AC10): 5 одновременных стартов практики + 10 параллельных
// записей событий → все 200, нет 500 / 57014 «statement timeout», прогретые старты < 1500 мс.
// Только API: business-2 создаёт кандидатов (link_only — без письма/SMS), кандидат — гость (anon-ключ, без входа).
// Голосовые сессии (start-voice-session) и AI НЕ вызываются. @load — вне обычного регресса: npm run test:load.
// Данные: 6 кандидатов «QA-AUTO-146331-<stamp>-…» (неудаляемые, квота business-2) + 6 попыток practice in_progress.
// Кейс: .qa/tests/candidate-call/CALL-020-start-attempt-under-load.md
import * as path from 'path';
import { test, expect, APIRequestContext } from '@playwright/test';
import { openWithApi, runStamp, SUPABASE_URL } from '../support/api';

test.use({ storageState: path.resolve(__dirname, '../../../auth/business-2.json') });

const SIMULATION_ID = process.env.QA_LOAD_SIMULATION_ID || '3218d624-6b97-4dd9-a6e9-7d30948ac5a3';
const PARALLEL_STARTS = 5;
const PARALLEL_EVENTS = 10;
const WARM_START_MAX_MS = 1500;

type Call = { fn: string; who: string; status: number; ms: number; text: string; json: any };

/** Вызов RPC с замером времени. auth не задан — гость (только anon-ключ). */
async function rpc(request: APIRequestContext, apikey: string, fn: string, body: Record<string, unknown>, who: string, auth?: string): Promise<Call> {
  const t0 = Date.now();
  const res = await request.post(`${SUPABASE_URL}/rest/v1/rpc/${fn}`, {
    headers: { apikey, authorization: auth || `Bearer ${apikey}`, 'content-type': 'application/json' },
    data: body,
  });
  const ms = Date.now() - t0;
  const text = await res.text();
  let json: any = null;
  try { json = JSON.parse(text); } catch { /* не JSON */ }
  return { fn, who, status: res.status(), ms, text: text.slice(0, 300), json };
}

const fmt = (c: Call) => `${c.fn} [${c.who}] ${c.status} ${c.ms}ms ${c.status === 200 ? '' : c.text}`;

test.describe('Звонок кандидата — старт попытки под нагрузкой (#146331)', () => {
  test('5 одновременных candidate_start_attempt (practice) + 10 параллельных candidate_record_event: все 200, нет 500/57014, прогретые старты < 1500 мс @desktop @data @load #146331', async ({ page }) => {
    test.setTimeout(180_000);
    const api = await openWithApi(page, '/candidates');
    const apikey = api.headers.apikey;
    const business = api.headers.authorization;
    const request = page.request;
    const managerId = await api.userId();

    const sims = (await (await api.get(`simulations?select=id,status&id=eq.${SIMULATION_ID}`)).json()) as { id: string; status: string }[];
    expect(sims[0]?.status, `окружение: симуляция ${SIMULATION_ID} у business-2 не активна (QA_LOAD_SIMULATION_ID)`).toBe('active');

    // 1–2. Подготовка: кандидат W (прогрев + цель событий) и L1…L5 (нагрузка), каждый доведён до «тех. проверка пройдена».
    const stamp = runStamp();
    const names = ['W', ...Array.from({ length: PARALLEL_STARTS }, (_, i) => `L${i + 1}`)].map((s) => `QA-AUTO-146331-${stamp}-${s}`);
    const tokens: Record<string, string> = {};
    for (const name of names) {
      const phone = '05000' + String(10000 + Math.floor(Math.random() * 90000));
      const c = await rpc(request, apikey, 'create_candidate', {
        p_fields: { full_name: name, phone, role_title: 'QA-AUTO-146331 נציג', simulation_id: SIMULATION_ID, assigned_manager_id: managerId },
      }, name, business);
      expect(c.status, fmt(c)).toBe(200);
      const token = c.json?.invite?.token as string;
      expect(token, `create_candidate без invite.token: ${c.text}`).toBeTruthy();
      tokens[name] = token;
      test.info().annotations.push({ type: 'test-data', description: `candidate ${name} ${c.json?.candidate_id} (неудаляем, писем нет)` });

      const open = await rpc(request, apikey, 'candidate_open_link', { p_token: token }, name);
      expect(open.status, fmt(open)).toBe(200);
      const consent = await rpc(request, apikey, 'candidate_give_consent', { p_token: token, p_shown_text: open.json?.candidate_legal_text ?? null }, name);
      expect(consent.status, fmt(consent)).toBe(200);
      const started = await rpc(request, apikey, 'candidate_tech_check', { p_token: token, p_event: 'started', p_details: {} }, name);
      expect(started.status, fmt(started)).toBe(200);
      const passed = await rpc(request, apikey, 'candidate_tech_check', { p_token: token, p_event: 'passed', p_details: { input_level: 0.5, verdict: 'good' } }, name);
      expect(passed.status, fmt(passed)).toBe(200);
    }

    // 3. Прогрев: одиночный старт W (его попытка — цель событий) и 15 параллельных чтений.
    const [warmName, ...loadNames] = names;
    const warm = await rpc(request, apikey, 'candidate_start_attempt', { p_token: tokens[warmName], p_attempt_type: 'practice', p_confirm_single_attempt: false }, warmName);
    expect(warm.status, fmt(warm)).toBe(200);
    const warmAttempt = warm.json?.attempt_id as string;
    expect(warmAttempt, `нет attempt_id: ${warm.text}`).toBeTruthy();
    const reads = await Promise.all(Array.from({ length: 15 }, () => rpc(request, apikey, 'get_current_legal_documents', { p_language: 'he' }, 'warmup')));
    for (const r of reads) expect(r.status, fmt(r)).toBe(200);

    // 4. Нагрузка: 5 стартов + 10 записей событий одновременно.
    const starts = loadNames.map((n) =>
      rpc(request, apikey, 'candidate_start_attempt', { p_token: tokens[n], p_attempt_type: 'practice', p_confirm_single_attempt: false }, n));
    const events = Array.from({ length: PARALLEL_EVENTS }, (_, k) =>
      rpc(request, apikey, 'candidate_record_event', {
        p_token: tokens[warmName], p_attempt_id: warmAttempt, p_kind: 'connection_warning',
        p_payload: { qa: 'QA-AUTO-146331', run: stamp, k }, p_offset_ms: 1000 + k,
      }, `${warmName}#${k}`));
    const [S, E] = await Promise.all([Promise.all(starts), Promise.all(events)]);
    const all = [...S, ...E];
    const log = all.map(fmt).join('\n');
    test.info().annotations.push({ type: 'load-result', description: log });

    // AC1: нет 500 / 57014 «statement timeout» — все 200.
    for (const c of all) {
      expect(c.text, `57014 / statement timeout\n${log}`).not.toMatch(/57014|statement timeout/i);
      expect(c.status, `${fmt(c)}\n${log}`).toBe(200);
    }
    // Старт создаёт отдельную практическую попытку каждому кандидату.
    for (const s of S) {
      expect(s.json, fmt(s)).toMatchObject({ status: 'in_progress', attempt_type: 'practice' });
      expect(s.json?.attempt_id, fmt(s)).toBeTruthy();
    }
    expect(new Set(S.map((s) => s.json?.attempt_id)).size, 'attempt_id стартов должны быть разными').toBe(PARALLEL_STARTS);
    // AC2 (замер времени): прогретые старты < 1500 мс.
    for (const s of S) expect(s.ms, `медленный старт под нагрузкой\n${log}`).toBeLessThan(WARM_START_MAX_MS);
  });
});
